"""Post-process an Alembic autogenerated migration.

    python scripts/fix_migration.py alembic/versions/<file>.py

1. NOT NULL columns added to existing tables get a server default, so the
   migration works on a database that already has rows.
2. Every newly created tenant table (one with a workspace_id column) gets the
   Row-Level Security policy — except platform tables, which are deliberately
   cross-tenant (see PLATFORM_TABLES).
"""

import re
import sys

# Have a workspace_id column but are read across workspaces by design.
PLATFORM_TABLES = {"workspace_members", "auth_tokens", "email_log", "subscriptions", "subscription_invoices", "admin_audit_log", "announcements"}


def fix(path: str) -> None:
    source = open(path).read()

    def add_default(match: re.Match) -> str:
        line = match.group(0)
        if "nullable=False" not in line or "server_default" in line:
            return line
        if "sa.Boolean" in line:
            return line.replace("nullable=False", "nullable=False, server_default=sa.false()")
        if "sa.String" in line:
            return line.replace("nullable=False", "nullable=False, server_default=''")
        if "sa.Numeric" in line or "sa.Integer" in line:
            return line.replace("nullable=False", "nullable=False, server_default='0'")
        if "sa.JSON" in line:
            return line.replace("nullable=False", "nullable=False, server_default='{}'")
        return line

    source = re.sub(r"op\.add_column\([^\n]*\)\)", add_default, source)
    upgrade = source[source.index("def upgrade()"):source.index("def downgrade()")]
    created = re.findall(r"op\.create_table\('(\w+)'", upgrade)
    tenant = [
        t for t in created
        if t not in PLATFORM_TABLES
        and re.search(rf"op\.create_table\('{t}',(?:(?!op\.create_table).)*?sa\.Column\('workspace_id'", upgrade, re.S)
    ]
    if tenant and "from app.core.rls import enable_rls" not in source:
        source = source.replace("import sqlalchemy as sa\n", "import sqlalchemy as sa\n\nfrom app.core.rls import enable_rls\n", 1)
    marker = "    # ### end Alembic commands ###\n"
    index = source.index(marker)
    source = source[:index] + marker + "".join(f"    enable_rls(op, '{t}')\n" for t in tenant) + source[index + len(marker):]
    open(path, "w").write(source)
    print("server defaults added; RLS enabled on:", tenant or "none")


if __name__ == "__main__":
    fix(sys.argv[1])
